  background: var(--accent-bg);
}
.projects-kpi__hero-value[data-v-5020e966] {
  font-size: 36px;
  font-weight: 800;
  color: var(--color-text-primary, #1a1a2e);
  line-height: 1;
}
.projects-kpi__hero-label[data-v-5020e966] {
  font-size: 13px;
  color: var(--color-text-muted, #9ca3af);
  font-weight: 400;
}

