  width: 32px;
  height: 32px;
  border-radius: 8px;
  background-color: color-mix(in oklab, var(--chart-3) 12%, transparent);
  color: var(--chart-3);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
