  color: var(--color-text-secondary, #6b7280);
  font-variant-numeric: tabular-nums;
}
.timeline-kpi__rail[data-v-59b927d8] {
  position: relative;
  flex: 1;
  min-width: 0;
  height: 4px;
  border-radius: 2px;
  background: var(--color-border, #e5e7eb);
}

/* Time already spent, up to today. */
.timeline-kpi__rail-fill[data-v-59b927d8] {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  border-radius: 2px;
  background: var(--iz-cat-5, #7c5cbf);
  transition: width 0.4s ease;
}

/* One tick per project deadline, so clustered due dates are visible. */
.timeline-kpi__rail-deadline[data-v-59b927d8] {
  position: absolute;
  top: 50%;
  width: 7px;
  height: 7px;
