  background: var(--bg-page, #f0f1f5);
  border: 1.5px solid var(--iz-cat-5, #7c5cbf);
}
.timeline-kpi__rail-now[data-v-59b927d8] {
  position: absolute;
  top: -4px;
  bottom: -4px;
  width: 2px;
  border-radius: 1px;
  background: var(--color-text-primary, #1a1a2e);
  transform: translateX(-1px);
}

/* ── Secondary Stats ── */
.timeline-kpi__stats[data-v-59b927d8] {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.timeline-kpi__stat[data-v-59b927d8] {
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
}
.timeline-kpi__stat-label[data-v-59b927d8] {
  font-size: 12px;
  color: var(--color-text-secondary, #6b7280);
  min-width: 0;
}
.timeline-kpi__stat-value[data-v-59b927d8] {
  margin-left: auto;
  white-space: nowrap;
  font-size: 13px;
  font-weight: 700;
  color: var(--color-text-primary, #1a1a2e);
  font-variant-numeric: tabular-nums;
}

